from __future__ import unicode_literals

from collections import Counter

from ute_common_config_files.raml.managed_object import ManagedObject
from ute_common_config_files.raml.xml import Xml
from ..scfc.exceptions import ScfcFixerException, NoSuchManagedObject, ExactlyOneManagedObjectExpected, DuplicatedDistNames


class Raml(Xml):

    CMDATA_PATH = '{*}cmData'
    ALL_MANAGED_OBJECTS_PATH = CMDATA_PATH + '/{*}managedObject'
    MANAGED_OBJECT_PATH = CMDATA_PATH + '/{*}managedObject[@distName="{dist_name}"]'
    MANAGED_OBJECTS_PATH = CMDATA_PATH + '/{*}managedObject[@class="{managed_object_class}"]'

    def find_managed_object(self, dist_name_or_class, id=None):
        """Returns an object or class representing given managed object node"""
        if id is None:
            managed_object_node = self._find_managed_object_node(dist_name_or_class)
            return ManagedObject(managed_object_node)
        else:
            dist_name_or_class = self.add_class_prefix_if_needed(dist_name_or_class)
            mo_list = [mo for mo in self.find_managed_objects(dist_name_or_class) if mo.id == id]
            if mo_list:
                return mo_list[0]
            else:
                self._raise_on_node_not_found(NoSuchManagedObject, self.xml,
                                              self.MANAGED_OBJECTS_PATH + ' with id = ' + str(id),
                                              managed_object_class=dist_name_or_class,
                                              id=id)

    def has_managed_object(self, managed_object_class, id=None):
        """Returns true if managed object exits in SCFC otherwise false, id is optional"""
        mos = self.find_managed_objects(managed_object_class)
        if mos and id is None:
            return True
        return True if any([True for mo in mos if mo.id == id]) else False

    def _find_managed_object_node(self, dist_name):
        return self._find_node_or_raise(self.MANAGED_OBJECT_PATH, dist_name=dist_name, exception_class=NoSuchManagedObject)

    def find_managed_objects(self, managed_object_class):
        """Returns a list of objects representing all managed objects of given class"""
        managed_object_class = self.add_class_prefix_if_needed(managed_object_class)
        managed_object_nodes = self._find_all_nodes(self.MANAGED_OBJECTS_PATH, managed_object_class=managed_object_class)
        return [ManagedObject(node) for node in managed_object_nodes]

    def find_all_managed_objects(self):
        """Returns a list of objects representing all managed objects"""
        managed_object_nodes = self._find_all_nodes(self.ALL_MANAGED_OBJECTS_PATH)
        return [ManagedObject(node) for node in managed_object_nodes]

    def find_single_managed_object(self, managed_object_class):
        """Returns an object representing a single existing managed object of given class.
        Raises an error if the number of matching objects is not 1."""
        managed_object_class = self.add_class_prefix_if_needed(managed_object_class)
        managed_object_node = self._find_single_managed_object_node(managed_object_class)
        return ManagedObject(managed_object_node)

    def _find_single_managed_object_node(self, managed_object_class):
        managed_object_class = self.add_class_prefix_if_needed(managed_object_class)
        return self._find_single_node_or_raise(self.MANAGED_OBJECTS_PATH, managed_object_class=managed_object_class,
                                               exception_class=ExactlyOneManagedObjectExpected)

    def add_managed_object(self, dist_name, version=None, class_prefix=None):
        """Adds an empty managed object"""
        version = version or self._find_version()
        managed_object_class = self._get_managed_object_class(dist_name)
        managed_object_class = self._get_class_name_with_prefix(managed_object_class, class_prefix) if class_prefix \
            else self.add_class_prefix_if_needed(managed_object_class)
        cmdata_node = self._find_cmdata_node()
        managed_object_node = self._add_element(cmdata_node, 'managedObject')
        managed_object_node.set('class', managed_object_class)
        managed_object_node.set('distName', dist_name)
        managed_object_node.set('operation', 'create')
        managed_object_node.set('version', version)
        self._fix_inner_indentation(managed_object_node)
        return ManagedObject(managed_object_node)

    def _get_managed_object_class(self, dist_name):
        last_part = dist_name.split('/')[-1]
        return last_part.split('-')[0]

    def _find_cmdata_node(self):
        return self._find_node_or_raise(self.CMDATA_PATH, exception_class=ScfcFixerException)

    def _find_version(self):
        managed_objects = self.find_all_managed_objects()
        if len(managed_objects) is 0:
            raise ScfcFixerException('Cannot find the version of SCFC because there are no managed objects')
        return managed_objects[0].version

    def remove_managed_object(self, dist_name):
        """Removes the managed object with given dist name"""
        node = self._find_managed_object_node(dist_name)
        self._remove_element(node)

    def remove_managed_objects(self, managed_object_class):
        """Removes all managed objects of given class"""
        managed_object_class = self.add_class_prefix_if_needed(managed_object_class)
        for mo in self.find_managed_objects(managed_object_class):
            mo.remove()

    def count_managed_objects(self, managed_object_class):
        """Returns number of managed objects of given class"""
        managed_object_class = self.add_class_prefix_if_needed(managed_object_class)
        return len(self.find_managed_objects(managed_object_class))

    def check_managed_objects_duplications(self):
        """Checks all classes of managed objects for duplicated distName parameter"""
        dist_names = [mo.dist_name for mo in self.find_all_managed_objects()]
        duplicated = [dist_name for dist_name, count in Counter(dist_names).items() if count > 1]
        if duplicated:
            exception_msg = "SCFC has managed objects with duplicated distName. Duplicated distNames:\n\t{}".format("\n\t".join(duplicated))
            raise DuplicatedDistNames(exception_msg)

    def add_class_prefix_if_needed(self, managed_object_class):
        """Checks if managed_object_class should have a prefix"""
        if self._uses_managed_object_prefixes() or not self._class_has_prefix(managed_object_class):
            managed_object_class_with_prefix = self._get_existing_class_name_with_prefix(managed_object_class)
            if managed_object_class_with_prefix is not None:
                return managed_object_class_with_prefix
        return managed_object_class

    def _uses_managed_object_prefixes(self):
        """Checks whether scfc is with prefix"""
        return self.find_all_managed_objects()[0].prefix is not None

    def _class_has_prefix(self, managed_object_class):
        """Checks whether managed object class attribute has prefix"""
        return True if len(managed_object_class.split(':')) == 2 else False

    def _get_existing_class_name_with_prefix(self, managed_object_class):
        mo_classes = sorted(list(set([mo.klass for mo in self.find_all_managed_objects() if mo.klass.endswith(managed_object_class)])))
        return mo_classes[0] if mo_classes else None

    def _get_class_name_with_prefix(self, managed_object_class, class_prefix):
        return '{prefix}:{mo_class}'.format(prefix=class_prefix, mo_class=managed_object_class)

    def change_managed_object_id_globally(self, managed_object, new_id):
        """Changes id in managed_object and every relation to this managed_object"""
        old_dist_name = managed_object.dist_name
        managed_object.id = new_id
        new_dist_name = managed_object.dist_name
        for mo in self.find_all_managed_objects():
            mo.dist_name = mo.dist_name.replace(old_dist_name + '/', new_dist_name + '/')
            self._change_params_distname(mo, old_dist_name, new_dist_name)
            for list_param in mo.find_all_list_params():
                self._change_params_distname(list_param, old_dist_name, new_dist_name)

    def _change_params_distname(self, obj, old_dist_name, new_dist_name):
        for param in obj.find_all_params():
            if param.value == old_dist_name:
                param.value = new_dist_name
            elif param.value is not None and param.value.startswith(old_dist_name + '/'):
                param.value = param.value.replace(old_dist_name, new_dist_name)
